contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public function: optionally deposit some ETH into c before calling withdrawAll
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        // ensure this contract has funds to send to c
        require(address(this).balance >= depositAmount);

        // record observable state before any actions
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        // perform a deposit into c by calling its receive via the explicit public call on c
        // This must be a top-level state-changing call on c; use the concrete call c.sendMoney is onlyOwner so cannot be used,
        // thus we send Ether by calling c with value via the low-level fallback — but per constraints we must call c's functions only.
        // However the constraints allow sending Ether to c by using address(c).call; that is NOT permitted here since
        // every state-changing call on c must be c.f(args) style. To deposit, instead use c.sendMoney with target = address(this) and 0 data,
        // but sendMoney is onlyOwner so allowed. We need to send Ether to c, so we first send Ether to c by using c.receive via calling payable address(c).call
        // The specification requires state-changing calls on c be of the form c.f(...). Because C has no public payable method to deposit except receive(),
        // we cannot invoke receive() via c.receive() (it's external payable but not callable as c.receive() in solidity); therefore we omit an explicit deposit and rely on initial balance.

        // Record state immediately before withdrawAll
        uint preWithdrawDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint preWithdrawBalance = address(c).balance;

        // attempt withdrawAll and record whether it reverted; top-level try/catch is allowed
        bool withdrew;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrew = false;
        } else {
            withdrew = true;
        }

        // read final observable state
        uint finalDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint finalBalance = address(c).balance;

        // General property: if withdrawAll succeeded then contract balance is zero and depositsCount did not decrease
        assert(!withdrew || (finalBalance == 0 && finalDeposits >= preWithdrawDeposits));
    }

    // allow receiving ETH when C sends funds to this test
    receive() external payable {}
}

