// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 depositAmount) internal {
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= depositAmount);
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        uint256 preWithdrawDeposits;
        try c.depositsCount() returns (uint256 __r) { preWithdrawDeposits = __r; } catch { return; }
        uint preWithdrawBalance = address(c).balance;
        bool withdrew;
        try c.withdrawAll() {
            withdrew = true;
        } catch {
            withdrew = false;
        }
        uint256 finalDeposits;
        try c.depositsCount() returns (uint256 __r) { finalDeposits = __r; } catch { return; }
        uint finalBalance = address(c).balance;
        assertTrue(!withdrew || (finalBalance == 0 && finalDeposits >= preWithdrawDeposits));
    }

    function testFuzz_run(uint256 depositAmount) public {
        _run(depositAmount);
    }

    receive() external payable {}
}
